+// State transfer module
+
+export function createStateTransfer(filePath) {
+  return {
+    exportJson(state) {
+      try {
+        if (typeof state !== 'object' || state === null) {
+          return '{}';
+        }
+
+        // Recursively sort object keys lexically
+        const sortedState = JSON.parse(JSON.stringify(state, (key, value) => {
+          if (typeof value === 'object' && value !== null) {
+            return Object.keys(value).sort().reduce((acc, key) => {
+              acc[key] = value[key];
+              return acc;
+            }, {});
+          }
+          return value;
+        }));
+
+        // Compact deterministic JSON
+        return JSON.stringify(sortedState, null, 0);
+      } catch (e) {
+        return '{}';
+      }
+    },
+
+    importJson(text) {
+      try {
+        const parsed = JSON.parse(text);
+
+        // Check if parsed is an object or array
+        if (typeof parsed !== 'object' || parsed === null) {
+          throw new Error('INVALID_IMPORT');
+        }
+
+        // Check for unsafe keys
+        if (Object.keys(parsed).some(key => ['__proto__', 'prototype', 'constructor'].includes(key))) {
+          throw new Error('INVALID_IMPORT');
+        }
+
+        // Recursively sort object keys
+        const canonicalized = JSON.parse(JSON.stringify(parsed, (key, value) => {
+          if (typeof value === 'object' && value !== null) {
+            return Object.keys(value).sort().reduce((acc, key) => {
+              acc[key] = value[key];
+              return acc;
+            }, {});
+          }
+          return value;
+        }));
+
+        // Write to file
+        const tempFilePath = filePath + '.tmp';
+        const dir = path.dirname(tempFilePath);
+        if (!fs.existsSync(dir)) {
+          fs.mkdirSync(dir, { recursive: true });
+        }
+
+        fs.writeFileSync(tempFilePath, JSON.stringify(canonicalized, null, 0));
+        fs.renameSync(tempFilePath, filePath);
+
+        return JSON.parse(JSON.stringify(canonicalized));
+      } catch (e) {
+        if (e.message === 'INVALID_IMPORT') {
+          throw new Error('INVALID_IMPORT');
+        }
+        throw new Error('STATE_CORRUPT');
+      }
+    },
+
+    read() {
+      try {
+        const data = fs.readFileSync(filePath, 'utf-8');
+        const parsed = JSON.parse(data);
+
+        // Check if parsed is an object or array
+        if (typeof parsed !== 'object' || parsed === null) {
+          return {};
+        }
+
+        // Check for unsafe keys
+        if (Object.keys(parsed).some(key => ['__proto__', 'prototype', 'constructor'].includes(key))) {
+          return {};
+        }
+
+        // Return deep clone
+        return JSON.parse(JSON.stringify(parsed));
+      } catch (e) {
+        return {};
+      }
+    }
+  };
+}
+
+// Ensure Node ESM stdlib only
+import { fs, path } from 'node:fs';
+import { path } from 'node:path';

